/* Read-only cross references between verified rules. User prose and saved values are untouched. */
(function(){
'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),norm=s=>String(s||'').trim().replace(/[’‘]/g,"'").replace(/\s+/g,' ').toLowerCase(),lang=()=>window.UKI18n?.language||'ko';
const entries=new Map(),aliases=new Map(),bySource=new Map(),kinds=['coreRules','weaponTraits','skills','fighterSubtypes','specialRules','equipment','territories','sideJobs','fighterTypes','gangTypes','tactics','scenarios'];
function add(entry){entries.set(entry.id,entry);for(const a of [entry.name,entry.nameKo,...entry.aliases||[]]){if(!a||a.length<2)continue;const k=norm(a);if(!aliases.has(k))aliases.set(k,entry.id);}}
for(const e of window.UK_RULE_TERMS?.entries||[])add({...e,edition:'n26'});
for(const kind of kinds)for(const row of window.RULES_DATA?.[kind]||[]){if(!row.source_verified||String(row.edition_slug||row.edition).toLowerCase()!=='n26'||!row.name||(!row.description&&!row.rule_data))continue;const id=kind+':'+row.id;add({id,name:row.name,nameKo:row.name_ko||window.UKI18n?.name(row.name),aliases:[window.UKI18n?.name(row.name),(row.name_ko||'').replace(/숏/g,'샷')],kind,row,edition:'n26'});bySource.set(row.id,id);}
for(const [alias,id]of Object.entries({'Active':'n26-core-model-statuses','액티브':'n26-core-model-statuses','Suppressed':'n26-core-model-statuses','서프레스드':'n26-core-model-statuses','Seriously Injured':'n26-core-model-statuses','중상':'n26-core-model-statuses','Seriously Damaged':'n26-core-model-statuses','중손상':'n26-core-model-statuses','Engaged':'n26-core-engagement','인게이지드':'n26-core-engagement','Out of Ammo':'n26-core-out-of-ammo','아웃 오브 애모':'n26-core-out-of-ammo'}))if(bySource.has(id))aliases.set(norm(alias),bySource.get(id));
const escapeRegex=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const pattern=new RegExp('(?<![A-Za-z0-9])(?:'+[...aliases.keys()].sort((a,b)=>b.length-a.length).map(a=>escapeRegex(a).replace(/ /g,'\\s+')).join('|')+')(?![A-Za-z0-9])','gi');
function lookup(query,options={}){const ed=String(options.edition||window.MMRuleReference?.currentEdition()||'n26').toLowerCase();if(ed!=='n26')return null;return entries.get(query)||entries.get(bySource.get(query))||entries.get(aliases.get(norm(query)))||null;}
function markup(text,self,edition){if(edition!=='n26')return esc(text);let out='',offset=0;for(const m of String(text).matchAll(pattern)){const e=lookup(aliases.get(norm(m[0])),{edition});if(!e||e.id===self)continue;if(/^[a-z]+$/.test(m[0])&&(['term-single','term-double'].includes(e.id)||['skills','weaponTraits','fighterSubtypes'].includes(e.kind)))continue;out+=esc(text.slice(offset,m.index))+`<button type="button" class="mmrr-term" data-rule-term="${esc(e.id)}" data-rule-edition="n26" aria-haspopup="dialog">${esc(m[0])}</button>`;offset=m.index+m[0].length;}return out+esc(text.slice(offset));}
function prose(en,ko,options={}){const edition=String(options.edition||'n26').toLowerCase(),self=options.self||lookup(options.row?.name,{edition})?.id||'',text=lang()==='en'?en:window.UKI18n?.t(ko||en,'ko')||ko||en;return `<p class="mmrr-description mmrr-linked-prose" data-rule-prose data-rule-en="${esc(en)}" data-rule-ko="${esc(ko||en)}" data-rule-self="${esc(self)}" data-rule-edition="${esc(edition)}" data-rule-language="${lang()}" data-i18n-ignore>${markup(text,self,edition)}</p>`;}
function refresh(){for(const p of document.querySelectorAll('[data-rule-prose]')){if(p.dataset.ruleLanguage===lang())continue;const focused=p.contains(document.activeElement)?document.activeElement?.dataset.ruleTerm:null,ordinal=focused?[...p.querySelectorAll('[data-rule-term]')].indexOf(document.activeElement):-1,text=lang()==='en'?p.dataset.ruleEn:window.UKI18n?.t(p.dataset.ruleKo,'ko')||p.dataset.ruleKo;p.innerHTML=markup(text,p.dataset.ruleSelf,p.dataset.ruleEdition);p.dataset.ruleLanguage=lang();if(focused){const next=[...p.querySelectorAll('[data-rule-term]')].filter(b=>b.dataset.ruleTerm===focused);(p.querySelectorAll('[data-rule-term]')[ordinal]||next[0])?.focus({preventScroll:true});}}}
function open(id,options={}){const e=lookup(id,options);if(!e)return false;const nested=!!document.querySelector('.mmrr-overlay');if(e.row)return window.MMRuleReference.open(e.kind,e.row,{edition:'n26',nested,activator:options.activator});const body=`<div class="mmrr-heading"><span class="mmrr-badge">N26</span><span data-i18n-en="Rule explanation" data-i18n-ko="규칙 설명">Rule explanation</span></div>`+(e.sections||[]).map(s=>`<section class="mmrr-term-section"><h3 data-i18n-en="${esc(s.title.en)}" data-i18n-ko="${esc(s.title.ko)}">${esc(s.title.en)}</h3>${prose(s.text.en,s.text.ko,{self:e.id,edition:'n26'})}</section>`).join('');return window.MMRuleReference.openContext(e.name,body,{nested,activator:options.activator,nameKo:e.nameKo});}
document.addEventListener('click',event=>{const b=event.target.closest?.('[data-rule-term]');if(!b)return;event.preventDefault();event.stopImmediatePropagation();open(b.dataset.ruleTerm,{edition:b.dataset.ruleEdition,activator:b});},true);
window.addEventListener('uk:languagechange',refresh);new MutationObserver(refresh).observe(document.body,{childList:true,subtree:true});window.MMRuleTerms={lookup,open,prose,refresh,get count(){return entries.size;}};
})();
